func TestMaxBipartiteMatchingExamples(t *testing.T) {
	// Left 0 and 1 both only reach right 0, so one of them stays unmatched.
	if got := maxBipartiteMatching(2, 2, [][]int{{0}, {0}}); got != 1 {
		t.Fatalf("shared neighbour = %d, want 1", got)
	}
	// Greedy in index order takes 0-0 and then strands left 1, unless it
	// augments: left 1 only reaches right 0, and left 0 can move to right 1.
	if got := maxBipartiteMatching(2, 2, [][]int{{0, 1}, {0}}); got != 2 {
		t.Fatalf("augmenting case = %d, want 2", got)
	}
	if got := maxBipartiteMatching(3, 3, [][]int{{}, {}, {}}); got != 0 {
		t.Fatalf("no edges = %d, want 0", got)
	}
}

// bruteMatching is exponential in the number of left vertices, which is why the
// random check below stays tiny.
func bruteMatching(n, m int, adj [][]int) int {
	used := make([]bool, m)
	var rec func(u int) int
	rec = func(u int) int {
		if u == n {
			return 0
		}
		best := rec(u + 1)
		for _, v := range adj[u] {
			if used[v] {
				continue
			}
			used[v] = true
			if got := 1 + rec(u+1); got > best {
				best = got
			}
			used[v] = false
		}
		return best
	}
	return rec(0)
}

func TestMaxBipartiteMatchingAgainstBruteForce(t *testing.T) {
	rng := rand.New(rand.NewSource(3))
	for trial := 0; trial < 400; trial++ {
		n := 1 + rng.Intn(8)
		m := 1 + rng.Intn(8)
