// TestMaxBipartiteMatchingPlantedPerfect hides a permutation inside a random
// graph. The matching cannot exceed n and the permutation achieves it, so the
// answer is exactly n with no reference implementation needed.
func TestMaxBipartiteMatchingPlantedPerfect(t *testing.T) {
	const n = 4000
	rng := rand.New(rand.NewSource(5))
	perm := rng.Perm(n)
	adj := make([][]int, n)
	for u := 0; u < n; u++ {
		adj[u] = append(adj[u], perm[u])
		for k := 0; k < 5; k++ {
			adj[u] = append(adj[u], rng.Intn(n))
		}
		rng.Shuffle(len(adj[u]), func(i, j int) { adj[u][i], adj[u][j] = adj[u][j], adj[u][i] })
	}
	if got := maxBipartiteMatching(n, n, adj); got != n {
		t.Fatalf("planted perfect matching = %d, want %d", got, n)
	}
}

// TestMaxBipartiteMatchingHallViolator has a block of left vertices crowded
// onto one right vertex, so the answer is bounded by the neighbourhood size of
// that block rather than by the number of left vertices.
func TestMaxBipartiteMatchingHallViolator(t *testing.T) {
	const crowd, free = 2000, 2000
	n, m := crowd+free, 1+free
	adj := make([][]int, n)
	for u := 0; u < crowd; u++ {
		adj[u] = []int{0}
	}
	for i := 0; i < free; i++ {
		adj[crowd+i] = []int{0, 1 + i}
	}
	if got := maxBipartiteMatching(n, m, adj); got != 1+free {
		t.Fatalf("Hall violator = %d, want %d", got, 1+free)
	}
}

// TestMaxBipartiteMatchingComplete is the min(n, m) ceiling on a dense graph.
func TestMaxBipartiteMatchingComplete(t *testing.T) {
	const n, m = 3000, 700
	adj := make([][]int, n)
	for u := range adj {
		adj[u] = make([]int, m)
		for v := range adj[u] {
			adj[u][v] = v
		}
	}
	if got := maxBipartiteMatching(n, m, adj); got != m {
		t.Fatalf("complete graph = %d, want %d", got, m)
	}
}

