// maxBipartiteMatching returns the size of a maximum matching between left
// vertices 0..n-1 and right vertices 0..m-1, where adj[u] lists the right
// vertices u can be matched to.
func maxBipartiteMatching(n, m int, adj [][]int) int {
	matchR := make([]int, m)
	for i := range matchR {
		matchR[i] = -1
	}
	matchL := make([]int, n)
	for i := range matchL {
		matchL[i] = -1
	}

	// A greedy pass takes the free edges first, so augmentation only has to
	// fix what greedy could not place.
	size := 0
	for u := 0; u < n; u++ {
		for _, v := range adj[u] {
			if matchR[v] == -1 {
				matchR[v], matchL[u] = u, v
				size++
				break
			}
		}
	}

	// seen[v] holds the id of the augmentation that last touched v. One id per
	// root keeps each right vertex to a single visit per search, which is what
	// bounds the search at O(E) instead of looping forever around a cycle.
	seen := make([]int, m)
	for i := range seen {
		seen[i] = -1
	}
	root := 0
	var try func(u int) bool
	try = func(u int) bool {
		for _, v := range adj[u] {
			if seen[v] == root {
				continue
			}
			seen[v] = root
			if matchR[v] == -1 || try(matchR[v]) {
				matchR[v], matchL[u] = u, v
				return true
			}
		}
		return false
	}

	for u := 0; u < n; u++ {
		if matchL[u] == -1 {
			root = u
			if try(u) {
				size++
			}
		}
	}
	return size
}

