// TestReservoirSampleIsUniform is the whole drill: every element of the stream
// has to survive with probability k/n, and no element may appear twice.
func TestReservoirSampleIsUniform(t *testing.T) {
	const n, k, trials = 100, 5, 60000
	stream := make([]int, n)
	for i := range stream {
		stream[i] = i
	}
	r := rand.New(rand.NewSource(2))
	count := make([]int, n)
	for i := 0; i < trials; i++ {
		got := reservoirSample(sliceStream(stream), k, r)
		if len(got) != k {
			t.Fatalf("trial %d returned %d values, want %d", i, len(got), k)
		}
		seen := map[int]bool{}
		for _, v := range got {
			if v < 0 || v >= n {
				t.Fatalf("trial %d returned %d, which is not in the stream", i, v)
			}
			if seen[v] {
				t.Fatalf("trial %d returned %d twice: %v", i, v, got)
			}
			seen[v] = true
			count[v]++
		}
	}
	want := float64(trials*k) / float64(n)
	for v, c := range count {
		if ratio := float64(c) / want; ratio < 0.9 || ratio > 1.1 {
			t.Fatalf("value %d kept %d times, want about %.0f (uniform would be within 10%%)", v, c, want)
		}
	}
}

